def semver_sort(versions):
    def parse_version(v):
        # Split build metadata (after '+')
        if '+' in v:
            v_no_build = v.split('+')[0]
        else:
            v_no_build = v

        # Split pre-release (after '-')
        if '-' in v_no_build:
            parts = v_no_build.split('-', 1)
            version_part = parts[0]
            prerelease_part = parts[1]
        else:
            version_part = v_no_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        major, minor, patch = map(int, version_part.split('.'))

        # Parse pre-release identifiers
        if prerelease_part:
            identifiers = prerelease_part.split('.')
            prerelease = tuple(identifiers)
        else:
            prerelease = None

        return (major, minor, patch, prerelease)

    def compare_prerelease(pre1, pre2):
        # None means no pre-release (higher precedence)
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:
            return 1  # no pre-release > pre-release
        if pre2 is None:
            return -1  # pre-release < no pre-release

        # Compare identifiers left to right
        for i in range(min(len(pre1), len(pre2))):
            id1 = pre1[i]
            id2 = pre2[i]

            is_digit1 = id1.isdigit()
            is_digit2 = id2.isdigit()

            if is_digit1 and is_digit2:
                cmp = int(id1) - int(id2)
                if cmp != 0:
                    return cmp
            elif is_digit1:
                return -1  # digits < non-digits
            elif is_digit2:
                return 1   # non-digits > digits
            else:
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        # If all shared identifiers are equal, fewer is first
        if len(pre1) < len(pre2):
            return -1
        elif len(pre1) > len(pre2):
            return 1
        else:
            return 0

    def compare_versions(parsed1, parsed2):
        major1, minor1, patch1, pre1 = parsed1
        major2, minor2, patch2, pre2 = parsed2

        if major1 != major2:
            return major1 - major2
        if minor1 != minor2:
            return minor1 - minor2
        if patch1 != patch2:
            return patch1 - patch2

        return compare_prerelease(pre1, pre2)

    # Parse all versions with their original index
    parsed = [(parse_version(v), i, v) for i, v in enumerate(versions)]

    # Sort by parsed version, keeping original order for equal precedence
    parsed.sort(key=lambda x: (x[0], x[1]))

    # Extract and return sorted version strings
    return [v for _, _, v in parsed]

